import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Libraries for RAG and AI applications","description":"A student-friendly comparison of LangChain, LlamaIndex, Haystack, DSPy, LangGraph, LiteLLM and direct SDKs without extra requirements.","frontmatter":{"title":"Libraries for RAG and AI applications","description":"A student-friendly comparison of LangChain, LlamaIndex, Haystack, DSPy, LangGraph, LiteLLM and direct SDKs without extra requirements."},"headers":[],"relativePath":"students/library-survey.md","filePath":"students/library-survey.md","lastUpdated":1794433168000}'),s={name:"students/library-survey.md"};function o(i,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="ai-libraries-what-they-do-and-when-to-use-them" tabindex="-1">AI libraries: what they do, and when to use them <a class="header-anchor" href="#ai-libraries-what-they-do-and-when-to-use-them" aria-label="Permalink to &quot;AI libraries: what they do, and when to use them&quot;">​</a></h1><p><strong>You do not need to install any library on this page.</strong> This is a comparison handout for the existing IS373 RAG assignment—not another deliverable. Build a small hosted application using tools you already have. Research before adding dependencies.</p><p>A <strong>library</strong> provides reusable functions or classes. A <strong>framework</strong> organizes how several components work together. An <strong>SDK</strong> helps your code call an external service. A <strong>model</strong> generates or classifies content. A <strong>database</strong> stores records and indexes. These are different layers; a RAG framework is not itself a vector database, a language model or a hosted server.</p><h2 id="the-problem-that-motivates-these-tools" tabindex="-1">The problem that motivates these tools <a class="header-anchor" href="#the-problem-that-motivates-these-tools" aria-label="Permalink to &quot;The problem that motivates these tools&quot;">​</a></h2><p>Imagine answering five questions using five approved club documents. Without a framework, your program must load sources, split text, create embeddings if selected, store and retrieve evidence, assemble context, call a model, and return sources. Those steps are valuable to understand. As a project grows, reusable libraries may eliminate repetitive integration code.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source documents → chunks and metadata → search/index → retrieved evidence</span></span>
<span class="line"><span>                                                      ↓</span></span>
<span class="line"><span>reader&#39;s question → query representation → retrieval → model → cited answer</span></span></code></pre></div><p>No framework verifies citations automatically. Your code and evaluation still need to prove that cited passages support the answer.</p><h2 id="six-useful-library-families" tabindex="-1">Six useful library families <a class="header-anchor" href="#six-useful-library-families" aria-label="Permalink to &quot;Six useful library families&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Main problem it solves</th><th>When it may help</th><th>What to watch out for</th></tr></thead><tbody><tr><td><strong>Direct model SDK + ordinary Python</strong></td><td>Call one model/provider and write your own retrieval logic</td><td>A small, transparent FastAPI app with one corpus</td><td>You must implement document/index interfaces and quality checks</td></tr><tr><td><strong><a href="https://docs.langchain.com/oss/python/learn" target="_blank" rel="noreferrer">LangChain</a></strong></td><td>Reusable model, document, retriever and tool integrations</td><td>You need to swap providers/components or reuse supported connectors</td><td>Abstractions and package versions can hide the exact data flow</td></tr><tr><td><strong><a href="https://developers.llamaindex.ai/python/framework/module_guides/indexing/" target="_blank" rel="noreferrer">LlamaIndex</a></strong></td><td>Data ingestion, chunks/nodes, indexing and querying over documents</td><td>The main challenge is searching and asking questions over a collection</td><td>Defaults may obscure index persistence, source IDs and retrieval choices</td></tr><tr><td><strong><a href="https://docs.haystack.deepset.ai/docs/concepts-overview" target="_blank" rel="noreferrer">Haystack</a></strong></td><td>Explicit components and wired document/AI pipelines</td><td>You want inspectable ETL and RAG stages with interchangeable retrievers</td><td>More pipeline configuration than a tiny application may need</td></tr><tr><td><strong><a href="https://docs.langchain.com/oss/python/learn" target="_blank" rel="noreferrer">LangGraph</a></strong></td><td>Stateful, multi-step agent/workflow orchestration</td><td>Long-running workflows with branches, interruptions or human review</td><td>Unnecessary for a simple retrieve-then-generate request</td></tr><tr><td><strong><a href="https://dspy.ai/getting-started/program-dont-prompt/" target="_blank" rel="noreferrer">DSPy</a></strong></td><td>Structured model tasks, metrics and program/prompt optimization</td><td>You have an evaluation set and want to improve extraction or answer quality</td><td>Optimization needs reliable examples, metrics and repeatable experiments</td></tr></tbody></table><p><strong>Related, but not a RAG framework:</strong> <a href="https://docs.litellm.ai/docs/python_sdk" target="_blank" rel="noreferrer">LiteLLM</a> standardizes calls to many model providers and can help compare or route models. It does <strong>not</strong> supply a complete document ingestion, indexing and citation workflow. Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/semantic-kernel/" target="_blank" rel="noreferrer">Semantic Kernel</a> is another option to research for enterprise AI integrations, especially in C#/.NET environments.</p><h2 id="what-should-an-is373-student-choose" tabindex="-1">What should an IS373 student choose? <a class="header-anchor" href="#what-should-an-is373-student-choose" aria-label="Permalink to &quot;What should an IS373 student choose?&quot;">​</a></h2><p><strong>Start with the app and server you already have.</strong> Your existing FastAPI app, SQLite or chosen database, and an authorized model API can be enough. Add a library only if you can name the repetitive work it removes, identify its new dependencies, and prove the output is still correct.</p><ul><li>If you have <strong>five short documents and one question endpoint</strong>, direct code often makes the retrieval trace easier to see.</li><li>If you need <strong>document loaders, splitters and vector-store adapters</strong>, inspect LangChain or LlamaIndex components rather than adopting a whole agent system.</li><li>If you need <strong>several explicit processing stages</strong>, investigate Haystack.</li><li>If you want to <strong>optimize a repeated extraction or generation task against a measured metric</strong>, investigate DSPy.</li><li>If you need <strong>stateful tool-using agents</strong>, look at LangGraph later; it is not required for this assignment.</li></ul><p>A production system may combine pieces from several libraries. You are <strong>not required to choose one framework for the whole application</strong>.</p><p>For the underlying concepts, use <a href="./embeddings">embeddings</a> and <a href="./chunking">chunking</a> before you decide which library abstracts them.</p><h2 id="a-tiny-experiment-for-learning" tabindex="-1">A tiny experiment for learning <a class="header-anchor" href="#a-tiny-experiment-for-learning" aria-label="Permalink to &quot;A tiny experiment for learning&quot;">​</a></h2><p>Choose one question whose expected source passage you already know. Compare <em>the same input and output contract</em> using your own retrieval code and one optional library component.</p><p>Record the real query, selected source IDs, relevant passage, whether it supports the claim, number of dependencies, and what a classmate can explain from the code. Do not claim one is faster, cheaper or more accurate without measuring. Avoid changing providers, embedding models and chunking choices simultaneously: that makes comparisons hard to interpret.</p><h3 id="copyable-ai-research-prompt" tabindex="-1">Copyable AI research prompt <a class="header-anchor" href="#copyable-ai-research-prompt" aria-label="Permalink to &quot;Copyable AI research prompt&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m an IS373 student. I already have [FastAPI app/database/model access].</span></span>
<span class="line"><span>My reader asks [question] about [permitted sources].</span></span>
<span class="line"><span>Compare direct Python with LangChain, LlamaIndex and Haystack for this task.</span></span>
<span class="line"><span>For each, show the smallest components needed, what code becomes hidden,</span></span>
<span class="line"><span>extra dependencies, persistence and citation responsibilities, and one</span></span>
<span class="line"><span>objective test. Link the CURRENT official docs for any suggested API.</span></span>
<span class="line"><span>Do not install libraries, rewrite my app, or claim a benchmark ran.</span></span>
<span class="line"><span>Finish by asking which tradeoff matters most to me.</span></span></code></pre></div><h3 id="a-note-from-the-ai" tabindex="-1">A note from the AI <a class="header-anchor" href="#a-note-from-the-ai" aria-label="Permalink to &quot;A note from the AI&quot;">​</a></h3><blockquote><p>I can generate working-looking framework code very quickly. But if you cannot tell what text was retrieved, where it came from, or whether the model relied on it, the abstraction has hidden a lesson you need to learn. Ask me to show the <strong>actual evidence objects and outputs</strong>, not just a green test summary.</p></blockquote><h2 id="what-still-belongs-to-you" tabindex="-1">What still belongs to you <a class="header-anchor" href="#what-still-belongs-to-you" aria-label="Permalink to &quot;What still belongs to you&quot;">​</a></h2><p>Regardless of library: explain your source permissions, chunk/graph representation, retrieval method, model/provider, access controls, persistence, missing-evidence behavior, costs and test results. Compare a simple keyword/structured baseline with your chosen vector or graph approach. The <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/projects/individual.md" target="_blank" rel="noreferrer">course brief</a> and Canvas are authoritative.</p><p><em>Primary documentation reviewed November 11, 2026. Library APIs and versions change: check official documentation and pin compatible dependencies before implementing anything.</em></p><p><a href="./from-app-studio">Start with your existing FastAPI application</a> · <a href="./data-choices">Compare database approaches</a> · <a href="./check">Evaluate your RAG</a></p>`,26)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
